<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Search, X } from '@lucide/vue'
import BaseInput from '../components/BaseInput.vue'
import BaseSelect from '../components/BaseSelect.vue'
import { getBrands, type Brand } from '../services/brands'
import { getCategories, type Category } from '../services/categories'
import { getProducts, type Product, type ProductFilters } from '../services/products'
import { useAuthStore } from '../stores/auth'

const auth = useAuthStore(); const products = ref<Product[]>([]); const categories = ref<Category[]>([]); const brands = ref<Brand[]>([]); const error = ref(''); const loading = ref(false)
const form = ref({ search: '', category_id: '', brand_id: '', is_active: '', has_stock: '', price_from: '', price_to: '' })
const canManage = computed(() => auth.hasPermission('catalog.manage')); const categoryOptions = computed(() => [{ value: '', label: 'Все категории' }, ...categories.value.map((category) => ({ value: String(category.id), label: category.name }))]); const brandOptions = computed(() => [{ value: '', label: 'Все бренды' }, ...brands.value.map((brand) => ({ value: String(brand.id), label: brand.name }))]); const stateOptions = [{ value: '', label: 'Любая активность' }, { value: '1', label: 'Активные' }, { value: '0', label: 'Скрытые' }]; const stockOptions = [{ value: '', label: 'Любой остаток' }, { value: '1', label: 'В наличии' }, { value: '0', label: 'Нет в наличии' }]
function filters(): ProductFilters { return { search: form.value.search || undefined, category_id: form.value.category_id ? Number(form.value.category_id) : undefined, brand_id: form.value.brand_id ? Number(form.value.brand_id) : undefined, is_active: form.value.is_active === '' ? undefined : form.value.is_active === '1', has_stock: form.value.has_stock === '' ? undefined : form.value.has_stock === '1', price_from: form.value.price_from || undefined, price_to: form.value.price_to || undefined } }
async function search(): Promise<void> { loading.value = true; try { products.value = await getProducts(filters()) } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Не удалось выполнить поиск.' } finally { loading.value = false } }
function reset(): void { form.value = { search: '', category_id: '', brand_id: '', is_active: '', has_stock: '', price_from: '', price_to: '' }; void search() }
async function load(): Promise<void> { try { [categories.value, brands.value] = await Promise.all([getCategories(), getBrands()]); await search() } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Не удалось загрузить фильтры.' } }
onMounted(load)
</script>
<template>
  <section class="mx-auto admin-page"><div class="mb-7"><p class="text-sm font-medium text-gray-500">Каталог</p><h1 class="mt-1 text-2xl font-bold tracking-tight text-gray-900 sm:text-3xl">Поиск товаров</h1><p class="mt-2 text-sm text-gray-500">Поиск по названию, slug или SKU варианта с фильтрами каталога.</p></div><p v-if="error" class="mb-4 rounded-lg border border-error-200 bg-error-50 px-4 py-3 text-sm text-error-500">{{ error }}</p><form class="rounded-xl border border-gray-200 bg-white p-5 shadow-card" @submit.prevent="search"><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><label class="text-sm font-medium text-gray-700 xl:col-span-2">Поиск<BaseInput v-model="form.search" class="mt-1.5" searchable placeholder="Название, slug или SKU" /></label><label class="text-sm font-medium text-gray-700">Категория<BaseSelect v-model="form.category_id" class="mt-1.5" :options="categoryOptions" accessible-name="Категория" searchable /></label><label class="text-sm font-medium text-gray-700">Бренд<BaseSelect v-model="form.brand_id" class="mt-1.5" :options="brandOptions" accessible-name="Бренд" searchable /></label><label class="text-sm font-medium text-gray-700">Активность<BaseSelect v-model="form.is_active" class="mt-1.5" :options="stateOptions" accessible-name="Активность" /></label><label class="text-sm font-medium text-gray-700">Остаток<BaseSelect v-model="form.has_stock" class="mt-1.5" :options="stockOptions" accessible-name="Остаток" /></label><label class="text-sm font-medium text-gray-700">Цена от<BaseInput v-model="form.price_from" class="mt-1.5" type="number" min="0" step="0.01" /></label><label class="text-sm font-medium text-gray-700">Цена до<BaseInput v-model="form.price_to" class="mt-1.5" type="number" min="0" step="0.01" /></label></div><div class="mt-5 flex gap-3"><button v-if="canManage" class="inline-flex items-center gap-2 rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60" :disabled="loading"><Search :size="18" />{{ loading ? 'Поиск…' : 'Найти' }}</button><button class="inline-flex items-center gap-2 rounded-lg px-4 py-2.5 text-sm font-semibold text-gray-600 hover:bg-gray-50" type="button" @click="reset"><X :size="18" />Сбросить</button></div></form><p class="mt-6 text-sm text-gray-500">Найдено: {{ products.length }}</p><div class="mt-3 overflow-hidden rounded-xl border border-gray-200 bg-white shadow-card"><div v-if="products.length" class="divide-y divide-gray-100"><article v-for="product in products" :key="product.id" class="p-4 sm:p-5"><div class="flex flex-wrap items-center gap-2"><h2 class="font-semibold text-gray-800">{{ product.name }}</h2><span class="admin-badge rounded-full px-2 py-1 text-xs font-medium" :class="product.is_active ? 'bg-success-50 text-success-600' : 'bg-gray-100 text-gray-500'">{{ product.is_active ? 'Активен' : 'Скрыт' }}</span></div><p class="mt-1 text-sm text-gray-500">{{ product.category.name }}<template v-if="product.brand"> · {{ product.brand.name }}</template> · /{{ product.slug }}</p></article></div><p v-else class="px-5 py-14 text-center text-sm text-gray-500">По выбранным условиям товары не найдены.</p></div></section>
</template>
